<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StudentController extends Controller {
 public function index(Request $r){$q=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('s.*','g.name as group_name');if($r->group)$q->where('g.id',$r->group);if($r->status)$q->where('s.status',$r->status);if($r->q){$x='%'.$r->q.'%';$q->where(fn($w)=>$w->where('s.last_name','like',$x)->orWhere('s.first_name','like',$x)->orWhere('s.middle_name','like',$x));}return view('admin.students.index',['students'=>$q->orderBy('s.last_name')->paginate(40)->withQueryString(),'groups'=>DB::table('study_groups')->where('active',1)->where('is_visible',1)->orderBy('name')->get()]);}
 public function create(){return view('admin.students.form',['student'=>null,'groups'=>$this->groups()]);}
 public function store(Request $r){$d=$this->validated($r);$id=DB::table('students')->insertGetId($d+['created_at'=>now(),'updated_at'=>now()]);$this->membership($id,$d['current_group_id']);return redirect()->route('admin.students.index')->with('success','Студент добавлен');}
 public function edit($id){$s=DB::table('students')->find($id);abort_if(!$s,404);return view('admin.students.form',['student'=>$s,'groups'=>$this->groups()]);}
 public function update(Request $r,$id){abort_unless(DB::table('students')->where('id',$id)->exists(),404);$d=$this->validated($r);DB::table('students')->where('id',$id)->update($d+['updated_at'=>now()]);if($d['status']==='active')$this->membership($id,$d['current_group_id']);return back()->with('success','Карточка сохранена');}
 public function destroy($id){$s=DB::table('students')->find($id);abort_if(!$s,404);DB::transaction(function()use($id){DB::table('students')->where('id',$id)->update(['status'=>'expelled','left_on'=>date('Y-m-d'),'updated_at'=>now()]);DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','updated_at'=>now()]);});return redirect()->route('admin.students.index')->with('success','Студент переведён в архив (отчислен)');}
 public function bulk(Request $r){return view('admin.students.bulk',['groups'=>$this->groups(),'selectedGroup'=>$r->integer('group')?:null]);}
 public function bulkStore(Request $r){$d=$r->validate(['current_group_id'=>'required|exists:study_groups,id','students'=>'required|string','enrolled_on'=>'nullable|date']);$lines=preg_split('/\R/u',trim($d['students']));$created=0;$skipped=[];DB::transaction(function()use($lines,$d,&$created,&$skipped){foreach($lines as $n=>$line){$line=trim(preg_replace('/[;\t]+/u',' ',trim($line)));if($line==='')continue;$p=preg_split('/\s+/u',$line,3);if(count($p)<2){$skipped[]='Строка '.($n+1).': '.$line;continue;}[$last,$first]=$p;$middle=$p[2]??null;$exists=DB::table('students')->where('last_name',$last)->where('first_name',$first)->where('middle_name',$middle)->where('status','active')->exists();if($exists){$skipped[]='Дубликат: '.$line;continue;}$id=DB::table('students')->insertGetId(['current_group_id'=>$d['current_group_id'],'last_name'=>$last,'first_name'=>$first,'middle_name'=>$middle,'status'=>'active','enrolled_on'=>$d['enrolled_on']??null,'created_at'=>now(),'updated_at'=>now()]);$this->membership($id,$d['current_group_id']);$created++;}});return redirect()->route('admin.students.index',['group'=>$d['current_group_id']])->with('success','Добавлено студентов: '.$created.($skipped?' · пропущено: '.count($skipped):''))->with('bulk_skipped',$skipped);}
 public function bulkAction(Request $r){$d=$r->validate(['student_ids'=>'required|array|min:1','student_ids.*'=>'integer|exists:students,id','action'=>'required|in:transfer,academic_leave,expel,graduate','target_group_id'=>'nullable|exists:study_groups,id','order_number'=>'required|string|max:100','order_date'=>'required|date','effective_on'=>'required|date','basis'=>'nullable|string|max:5000']);if($d['action']==='transfer')abort_if(empty($d['target_group_id']),422,'Выберите группу назначения.');$p=$r->attributes->get('academic_period');abort_if(!$p,422,'Не выбран учебный период.');$type=['transfer'=>'transfer','academic_leave'=>'academic_leave','expel'=>'expulsion','graduate'=>'graduation'][$d['action']];$title=['transfer'=>'Массовый перевод студентов','academic_leave'=>'Академический отпуск','expel'=>'Отчисление студентов','graduate'=>'Выпуск студентов'][$d['action']];DB::transaction(function()use($r,$d,$p,$type,$title){$orderId=DB::table('academic_orders')->insertGetId(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date'],'student_id'=>null,'type'=>$type,'title'=>$title,'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['student_ids'] as $id){$s=DB::table('students')->find($id);if(!$s)continue;$to=$d['action']==='transfer'?$d['target_group_id']:null;DB::table('student_movements')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'type'=>$type,'from_group_id'=>$s->current_group_id,'to_group_id'=>$to,'effective_on'=>$d['effective_on'],'academic_order_id'=>$orderId,'order_number'=>$d['order_number'],'order_date'=>$d['order_date'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);if($d['action']==='transfer'){DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);DB::table('students')->where('id',$id)->update(['current_group_id'=>$to,'status'=>'active','left_on'=>null,'updated_at'=>now()]);DB::table('student_group_memberships')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'study_group_id'=>$to,'starts_on'=>$d['effective_on'],'ends_on'=>null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);}else{$status=['academic_leave'=>'academic_leave','expel'=>'expelled','graduate'=>'graduated'][$d['action']];$up=['status'=>$status,'updated_at'=>now()];if(in_array($status,['expelled','graduated']))$up['left_on']=$d['effective_on'];DB::table('students')->where('id',$id)->update($up);DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);}}});return redirect()->route('academic.movements')->with('success','Приказ зарегистрирован, движение студентов записано в историю');}
 private function groups(){return DB::table('study_groups')->where('active',1)->orderBy('name')->get();}
 private function validated(Request $r){return $r->validate(['current_group_id'=>'required|exists:study_groups,id','last_name'=>'required|max:100','first_name'=>'required|max:100','middle_name'=>'nullable|max:100','status'=>'required|in:active,academic_leave,expelled,graduated,transferred','enrolled_on'=>'nullable|date','left_on'=>'nullable|date']);}
 private function membership($studentId,$groupId){$period=DB::table('academic_periods')->where('is_current',1)->first()?:DB::table('academic_periods')->orderByDesc('starts_on')->first();if($period)DB::table('student_group_memberships')->updateOrInsert(['student_id'=>$studentId,'academic_period_id'=>$period->id],['study_group_id'=>$groupId,'status'=>'active','updated_at'=>now(),'created_at'=>now()]);}
}
